<script setup lang="ts">
import {ref,onMounted,onUnmounted,nextTick} from 'vue';
type Choice={index:number;label:string;disabled:boolean;group:string};
const menu=ref<HTMLElement|null>(null),active=ref<HTMLSelectElement|null>(null),choices=ref<Choice[]>([]),highlight=ref(-1),position=ref<Record<string,string>>({});
const menuId='pms-shared-select-menu';let oldExpanded:string|null=null,oldControls:string|null=null,oldDescendant:string|null=null,search='',searchAt=0,observer:MutationObserver|undefined;
function eligible(target:EventTarget|null){const select=target instanceof Element?target.closest('select'):null;return select instanceof HTMLSelectElement&&select.closest('.pms-workspace')&&!select.multiple&&select.size<=1&&!select.disabled?select:null;}
function restore(select:HTMLSelectElement,name:string,value:string|null){value===null?select.removeAttribute(name):select.setAttribute(name,value);}
function close(){if(active.value){restore(active.value,'aria-expanded',oldExpanded);restore(active.value,'aria-controls',oldControls);restore(active.value,'aria-activedescendant',oldDescendant);}active.value=null;choices.value=[];observer?.disconnect();observer=undefined;search='';}
function place(){const select=active.value;if(!select)return;if(!select.isConnected||select.disabled||!select.getClientRects().length){close();return;}const rect=select.getBoundingClientRect(),styles=getComputedStyle(select.closest('.pms-workspace')!);const below=innerHeight-rect.bottom-12,above=rect.top-12;const up=below<160&&above>below;const height=Math.min(280,Math.max(80,(up?above:below)-8));position.value={left:Math.max(8,Math.min(rect.left,innerWidth-Math.min(Math.max(rect.width,160),innerWidth-16)-8))+'px',width:Math.min(Math.max(rect.width,160),innerWidth-16)+'px',maxHeight:height+'px',...(up?{bottom:innerHeight-rect.top+5+'px'}:{top:rect.bottom+5+'px'}),'--pms-surface':styles.getPropertyValue('--pms-surface'),'--pms-border':styles.getPropertyValue('--pms-border'),'--pms-text':styles.getPropertyValue('--pms-text'),'--pms-muted':styles.getPropertyValue('--pms-muted'),'--pms-primary':styles.getPropertyValue('--pms-primary'),'--pms-primary-soft':styles.getPropertyValue('--pms-primary-soft')};}
function read(){const select=active.value;if(!select)return;choices.value=Array.from(select.options).map((option,index)=>({index,label:option.label,disabled:option.disabled||(option.parentElement instanceof HTMLOptGroupElement&&option.parentElement.disabled),group:option.parentElement instanceof HTMLOptGroupElement?option.parentElement.label:''}));highlight.value=select.selectedIndex;place();}
function reveal(){const select=active.value;if(!select)return;select.setAttribute('aria-activedescendant',menuId+'-'+highlight.value);void nextTick(()=>menu.value?.querySelector<HTMLElement>('[data-highlighted=true]')?.scrollIntoView({block:'nearest'}));}
function open(select:HTMLSelectElement){close();oldExpanded=select.getAttribute('aria-expanded');oldControls=select.getAttribute('aria-controls');oldDescendant=select.getAttribute('aria-activedescendant');active.value=select;select.setAttribute('aria-expanded','true');select.setAttribute('aria-controls',menuId);select.focus({preventScroll:true});read();reveal();observer=new MutationObserver(read);observer.observe(select,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:['disabled','label','selected']});}
function choose(index:number){const select=active.value;if(!select||choices.value[index]?.disabled)return;close();select.selectedIndex=index;select.focus({preventScroll:true});select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));}
function pointer(e:PointerEvent){const select=eligible(e.target);if(select&&e.button===0){e.preventDefault();active.value===select?close():open(select);}else if(active.value&&!menu.value?.contains(e.target as Node))close();}
function nativeMouse(e:Event){if(eligible(e.target))e.preventDefault();}
function move(direction:number){const enabled=choices.value.filter(c=>!c.disabled);if(!enabled.length)return;const index=enabled.findIndex(c=>c.index===highlight.value);highlight.value=(index<0?enabled[direction>0?0:enabled.length-1]:enabled[(index+direction+enabled.length)%enabled.length]).index;reveal();}
function keys(e:KeyboardEvent){const select=eligible(e.target);if(!select)return;if(['ArrowDown','ArrowUp','Enter',' '].includes(e.key)){e.preventDefault();e.stopPropagation();if(!active.value)open(select);else if(e.key==='ArrowDown'||e.key==='ArrowUp')move(e.key==='ArrowDown'?1:-1);else choose(highlight.value);}else if(active.value===select){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close();}else if(e.key==='Tab')close();else if(e.key==='Home'||e.key==='End'){e.preventDefault();const enabled=choices.value.filter(c=>!c.disabled);highlight.value=(e.key==='Home'?enabled[0]:enabled[enabled.length-1])?.index??-1;reveal();}else if(e.key.length===1&&!e.ctrlKey&&!e.metaKey&&!e.altKey){e.preventDefault();search=Date.now()-searchAt>700?e.key:search+e.key;searchAt=Date.now();const match=choices.value.find(c=>!c.disabled&&c.label.toLowerCase().startsWith(search.toLowerCase()));if(match){highlight.value=match.index;reveal();}}}}
function focus(e:FocusEvent){if(active.value&&e.target!==active.value&&!menu.value?.contains(e.target as Node))close();}
function scroll(e:Event){if(active.value&&!menu.value?.contains(e.target as Node))close();}
onMounted(()=>{document.addEventListener('pointerdown',pointer,true);document.addEventListener('mousedown',nativeMouse,true);document.addEventListener('click',nativeMouse,true);document.addEventListener('keydown',keys,true);document.addEventListener('focusin',focus,true);document.addEventListener('scroll',scroll,true);window.addEventListener('resize',close);});
onUnmounted(()=>{close();document.removeEventListener('pointerdown',pointer,true);document.removeEventListener('mousedown',nativeMouse,true);document.removeEventListener('click',nativeMouse,true);document.removeEventListener('keydown',keys,true);document.removeEventListener('focusin',focus,true);document.removeEventListener('scroll',scroll,true);window.removeEventListener('resize',close);});
</script>
<template><Teleport to="body"><div v-if="active" ref="menu" :id="menuId" class="pms-shared-select-menu" :style="position" role="listbox" :aria-label="active.getAttribute('aria-label')||'Select an option'" @pointerdown.prevent><template v-for="(choice,index) in choices" :key="choice.index"><div v-if="choice.group&&choice.group!==choices[index-1]?.group" class="pms-select-group">{{choice.group}}</div><button type="button" tabindex="-1" role="option" :id="menuId+'-'+choice.index" :aria-selected="active.selectedIndex===choice.index" :aria-disabled="choice.disabled" :disabled="choice.disabled" :data-highlighted="highlight===choice.index" @pointermove="highlight=choice.index" @click="choose(choice.index)"><span>{{choice.label}}</span><svg v-if="active.selectedIndex===choice.index" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg></button></template></div></Teleport></template>
